"""Opt-in mitmweb hook entry; the launch config is generated by ConsoleRunner."""

import asyncio
from mitmproxy import ctx

from .runtime import RecordingRuntime


class AndroidBreakpoints:
    def __init__(self, config):
        self.config = config
        self.runtime = None
        self.owner_task = None

    async def running(self):
        try:
            self.runtime = RecordingRuntime(ctx.master, self.config['outdir'],
                                            self.config['capture_id'], self.config['device_id'])
            ctx.options.update(stream_large_bodies='256k')
            await self.runtime.start()
        except Exception:
            ctx.master.shutdown()
            raise
        self.owner_task = asyncio.create_task(self.watch_owner())

    async def watch_owner(self):
        from ..ios_setup import process_identity
        while True:
            await asyncio.sleep(0.5)
            try:
                identity = await asyncio.to_thread(process_identity, self.config['owner_pid'])
            except Exception:
                identity = None
            if identity != self.config['owner_identity']:
                await self.runtime.close()
                ctx.master.shutdown()
                return

    def next_layer(self, nextlayer):
        if self.runtime:
            self.runtime.addon.next_layer(nextlayer)

    def requestheaders(self, flow):
        self.runtime.requestheaders(flow)

    async def request(self, flow):
        await self.runtime.request(flow)

    def responseheaders(self, flow):
        self.runtime.responseheaders(flow)

    async def response(self, flow):
        await self.runtime.response(flow)

    def error(self, flow):
        self.runtime.error(flow)

    def client_disconnected(self, client):
        if self.runtime:
            self.runtime.addon.client_disconnected(client)

    async def done(self):
        if self.owner_task:
            self.owner_task.cancel()
            await asyncio.gather(self.owner_task, return_exceptions=True)
        if self.runtime:
            await self.runtime.close()
